import sys; sys.path.insert(0, __import__("pathlib").Path(__file__).resolve().parents[1].as_posix())
from explications import *

ENTREES = [
    ("## 🗝️ Vocabulaire", 'fin', apropos("Sur les anciennes guirlandes de Noël, quand **une seule ampoule grille**, **toute la guirlande s'éteint**. Sur les guirlandes LED modernes, les autres restent allumées. Pourquoi, à ton avis ?", "Les anciennes ampoules sont branchées **les unes après les autres**, **en série** : un seul chemin pour le courant, donc une coupure arrête tout. Les montages modernes utilisent des **branches en parallèle** : chaque LED a son propre chemin.\n\nDans cette séance, tu vas apprendre à **calculer** la résistance qui protège une LED et à comprendre ces deux façons de brancher des composants.")),
    ("## 1.", 'fin', clair("Une LED est une **diode** qui émet de la lumière. Elle laisse passer le courant **dans un seul sens** : de l'**anode (+)** vers la **cathode (−)**.\n\nPour s'allumer, elle a besoin d'une tension minimale appelée **tension de seuil** ($V_F$, environ 2 V pour une LED rouge). Ensuite, **le courant augmente très vite** : si rien ne le limite, la LED est détruite. D'où la **résistance de limitation**.") + "\n" + verifie(
        ("Une LED ne s'allume pas alors que le circuit est complet. Quelle est la première chose à vérifier ?", "Le **sens de branchement** : la patte longue (anode) doit aller vers le **+**."),
        ("Que signifie $V_F$ pour une LED ?", "La **tension de seuil** (« forward voltage ») : la tension qui apparaît aux bornes de la LED quand elle est allumée (environ 2 V pour une rouge)."),
        ("Pourquoi une LED ne supporte-t-elle pas 9 V directement ?", "Elle laisse alors passer un courant **beaucoup trop fort** et elle est détruite. Il faut une résistance en série.")) + "\n" + retenir("La LED est une diode : elle a un sens (anode +, cathode −).", "Elle a une tension de seuil $V_F$ et un courant normal $I_F$ (≈ 20 mA).")),
    ("## 2.", 'fin', clair("C'est la **même loi d'Ohm** que dans la séance S01 : $U = R \\times I$. Ici, on l'utilise sur la résistance qui protège la LED.\n\nTrois réflexes : **écrire ce qu'on cherche**, **convertir en V, A, Ω**, puis **calculer** avec la bonne formule.") + "\n" + verifie(
        ("Une résistance de 220 Ω est traversée par 15 mA. Quelle tension a-t-elle à ses bornes ?", "$U = R \\times I = 220 \\times 0{,}015 = 3{,}3\\,\\mathrm{V}$ (15 mA = 0,015 A)."),
        ("Une tension de 6 V est appliquée à 300 Ω. Quel courant passe ?", "$I = \\dfrac{U}{R} = \\dfrac{6}{300} = 0{,}02\\,\\mathrm{A} = 20\\,\\mathrm{mA}$."),
        ("Pourquoi convertit-on les mA en A avant de calculer ?", "Parce que la loi d'Ohm donne un bon résultat avec les **unités de base** : volts, ampères et ohms.")) + "\n" + erreurs("Utiliser 20 au lieu de 0,02 pour 20 mA : le résultat est faux d'un facteur 1 000.")),
    ("## 3.", 'fin', clair("Une LED rouge « garde » environ 2 V pour elle. Si tu l'alimentes avec 9 V, il reste **7 V en trop**. C'est la **résistance** qui doit les absorber, tout en laissant passer 20 mA.\n\n**Méthode en 4 étapes :**\n\n1. **Tension à absorber** : $V_R = V_{alim} - V_F$.\n2. **Courant voulu** : $I_F = 20\\,\\mathrm{mA} = 0{,}02\\,\\mathrm{A}$.\n3. **Calcul** : $R = \\dfrac{V_R}{I_F}$.\n4. **Choix** : on prend la valeur **normalisée** (série E24) **au-dessus** du résultat.") + "\n" + verifie(
        ("Calcule la résistance pour une LED rouge (2 V, 20 mA) alimentée en 5 V.", "$V_R = 5 - 2 = 3\\,\\mathrm{V}$ ; $R = \\dfrac{3}{0{,}02} = 150\\,\\Omega$. 150 Ω est une valeur normalisée."),
        ("Calcule la résistance pour une LED verte (2,1 V, 20 mA) alimentée en 12 V.", "$V_R = 12 - 2{,}1 = 9{,}9\\,\\mathrm{V}$ ; $R = \\dfrac{9{,}9}{0{,}02} = 495\\,\\Omega$ ; valeur normalisée au-dessus : **510 Ω**."),
        ("Calcule la résistance pour une LED rouge (2 V, 20 mA) alimentée en 3,3 V.", "$V_R = 3{,}3 - 2 = 1{,}3\\,\\mathrm{V}$ ; $R = \\dfrac{1{,}3}{0{,}02} = 65\\,\\Omega$ ; valeur normalisée au-dessus : **68 Ω**.")) + "\n" + erreurs("Oublier de retirer $V_F$ : on calculerait $R = 9 / 0{,}02 = 450\\,\\Omega$, alors que la bonne valeur est 350 Ω.", "Prendre une valeur **plus petite** que le résultat : la LED reçoit trop de courant.") + "\n" + retenir("$R = \\dfrac{V_{alim} - V_F}{I_F}$, avec $I_F$ en ampères.", "On choisit la valeur normalisée **juste au-dessus** du résultat.")),
    ("## 4.", 'fin', clair("**En série**, les composants forment **un seul chemin**, comme des personnes qui marchent en file indienne : **le même courant** traverse tout le monde, et **la tension se partage**. Si un maillon est coupé, **tout s'arrête**.\n\n**En parallèle**, le courant a **plusieurs chemins**, comme les voies d'une autoroute : **la tension est la même** sur chaque branche, et **le courant se partage**. Si une branche est coupée, **les autres continuent**.") + "\n" + verifie(
        ("Deux LED rouges (2 V, 20 mA) sont en série sur 9 V. Calcule la résistance.", "$R = \\dfrac{9 - 2 - 2}{0{,}02} = 250\\,\\Omega$ ; valeur normalisée : **270 Ω**."),
        ("Deux LED rouges sont en parallèle sur 9 V. Quel courant total faut-il ?", "$I_{total} = 2 \\times 20 = 40\\,\\mathrm{mA}$ ; et $R = \\dfrac{9 - 2}{0{,}04} = 175\\,\\Omega$ (valeur normalisée : 180 Ω)."),
        ("Une LED grille. Dans quel montage les autres restent-elles allumées ?", "Dans le montage **en parallèle** : chaque LED a son propre chemin.")) + "\n" + retenir("Série : **même courant**, la tension se partage, une panne coupe tout.", "Parallèle : **même tension**, le courant se partage, les autres branches continuent.")),
    ("## 5.", 'fin', clair("Une **datasheet** est la « notice » du composant, écrite par le fabricant. Tu n'as pas besoin de tout lire : cherche **trois choses** :\n\n1. la **tension directe** $V_F$ ;\n2. le **courant normal** $I_F$ ;\n3. les **valeurs maximales** à ne jamais dépasser.\n\nPour calculer, on prend les valeurs **typiques** (« typ. ») ; on vérifie ensuite qu'on reste **sous les valeurs maximales** (« max »).") + "\n" + verifie(
        ("Quelle valeur de la datasheet utilise-t-on pour calculer la résistance ?", "Les valeurs **typiques** de $V_F$ et de $I_F$."),
        ("Pourquoi ne prend-on pas $I_{FM} = 100\\,\\mathrm{mA}$ pour calculer ?", "C'est un courant **maximal instantané**, jamais un courant de fonctionnement normal : on utilise $I_F = 20\\,\\mathrm{mA}$.")) ),
    ("## 6.", 'fin', clair("Le multimètre se branche **différemment** selon ce qu'on mesure. Pour t'en souvenir :\n\n- **Tension** : en **parallèle** (on mesure « entre deux points »).\n- **Courant** : en **série** (le courant doit **traverser** l'appareil).\n- **Résistance** : **hors tension**, composant sorti du circuit.") + "\n" + erreurs("Brancher l'ampèremètre **en parallèle** : on crée un court-circuit et on peut détruire l'appareil.", "Mesurer une résistance alors que le circuit est alimenté : la mesure est fausse.") + "\n" + verifie(
        ("Comment branche-t-on le multimètre pour mesurer la tension aux bornes d'une LED ?", "**En parallèle** de la LED, en mode tension continue (DCV)."),
        ("Pour mesurer le courant dans le circuit, où place-t-on l'ampèremètre ?", "**En série** : on ouvre le circuit et on y intercale l'appareil."),
        ("Peut-on mesurer la valeur d'une résistance dans un circuit alimenté ?", "Non : il faut couper l'alimentation et, si possible, sortir la résistance du circuit.")) + "\n" + retenir("V en parallèle, A en série, Ω hors tension.")),
]
